//! Canonical Option text and actual native content replacement.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><select id=select><optgroup id=optgroup label=Group><option id=option>One</option></optgroup><option id=second value=two label=Second>Two</option></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://option-text.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn option_text_canonical_interface_descriptors_and_initial_text(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),C=HTMLOptionElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'text');if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get text'||a.set.name!=='set text'||Object.hasOwn(x,'text')||x.text!=='One')throw 'canonical option text';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal construction';"#);}
#[test]
fn option_text_inert_html_aware_getter_and_raw_replace_all_preserve_actual_nodes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','option'),span=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),script=owner.createElementNS('http://www.w3.org/1999/xhtml','script');span.appendChild(owner.createTextNode(' \ud800 B\t'));x.appendChild(owner.createTextNode(' A '));x.appendChild(span);script.textContent='Hidden';x.appendChild(script);if(x.text!=='A \ud800 B')throw 'HTML aware getter';var old=x.firstChild,list=x.childNodes,watch=new MutationObserver(function(){});watch.observe(x,{childList:true});x.text=' R\ud800\nZ ';var records=watch.takeRecords();if(x.text!=='R\ud800 Z'||x.textContent!==' R\ud800\nZ '||old.parentNode!==null||old.data!==' A '||list.length!==1||x.firstChild.nodeType!==3||x.firstChild.ownerDocument!==owner||records.length!==1||records[0].target!==x||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==x.firstChild)throw 'real inert replace all';x.text='';if(x.text!==''||x.firstChild!==null||list.length!==0)throw 'actual empty replacement';"#);}
#[test]
fn option_text_native_replace_all_updates_fallback_value_label_and_selected_caption(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),old=x.firstChild,list=x.childNodes,watch=new MutationObserver(function(){});watch.observe(x,{childList:true});x.text='  Ready\n now  ';var records=watch.takeRecords();if(x.text!=='Ready now'||x.textContent!=='  Ready\n now  '||x.value!=='Ready now'||x.label!=='Ready now'||old.parentNode!==null||old.data!=='One'||list.length!==1||x.firstChild===old||records.length!==1||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==x.firstChild)throw 'native exact replace all';"#);let c=&f.controls[&select];let state=c.select.as_ref().unwrap();assert_eq!((state.options[0].label.as_str(),state.options[0].value.as_str(),c.caption.as_str(),c.value.text()),("Ready now","Ready now","Ready now","Ready now".into()));run(&mut d,&mut f,&mut p,"x.text='';if(x.text!==''||x.value!==''||x.label!==''||list.length!==0||x.firstChild!==null)throw 'native clear';");assert_eq!(f.controls[&select].value.text(),"");assert_eq!(f.controls[&select].caption,"");}
#[test]
fn option_text_native_explicit_metadata_and_unselected_state_remain_independent(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('second'),v=x.getAttributeNode('value'),l=x.getAttributeNode('label'),select=document.getElementById('select');x.text='Different content';if(x.text!=='Different content'||x.textContent!=='Different content'||x.value!=='two'||x.label!=='Second'||x.getAttributeNode('value')!==v||x.getAttributeNode('label')!==l||select.value!=='One'||select.selectedIndex!==0)throw 'independent explicit metadata';");let c=&f.controls[&select];let state=c.select.as_ref().unwrap();assert_eq!((state.options[1].label.as_str(),state.options[1].value.as_str(),c.caption.as_str(),c.value.text()),("Second","two","One","One".into()));}
#[test]
fn option_text_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLOptionElement,a=Object.getOwnPropertyDescriptor(C.prototype,'text'),calls=0;if(C===HTMLOptionElement||a.get.call(x)!=='One')throw 'captured area accessor';"#);p.set_location(&crate::navigation::address("https://other-time.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://option-text.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'area origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.


#[test]
fn option_text_brands_author_shadow_and_saved_constructor_use_canonical_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),C=HTMLOptionElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'text'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','option'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OPTION')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'concrete getter brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'text',{value:'author',writable:true,configurable:true});a.set.call(x,'Native');if(x.text!=='author'||a.get.call(x)!=='Native'||x.textContent!=='Native')throw 'canonical text authority';delete x.text;delete window.HTMLOptionElement;if(x.text!=='Native'||Object.hasOwn(x,'text')||!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);}
#[test]
fn option_text_conversion_reentry_abrupt_symbol_and_domstring_null_are_exact(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),old=x.firstChild,watch=new MutationObserver(function(){});watch.observe(x,{childList:true});var calls=0;x.text={toString:function(){calls++;x.textContent='Author';return ' R\ud800\nZ ';}};var records=watch.takeRecords();if(calls!==1||x.text!=='R\ud800 Z'||x.textContent!==' R\ud800\nZ '||old.parentNode!==null||records.length!==2||records[1].removedNodes[0].data!=='Author'||records[1].addedNodes[0]!==x.firstChild)throw 'conversion reentry replaces current children';var marker={},caught;try{x.text={toString:function(){x.textContent='Author effect';throw marker;}};}catch(e){caught=e;}if(caught!==marker||x.text!=='Author effect'||watch.takeRecords().length!==1)throw 'abrupt conversion preserves effects';caught=false;try{x.text=Symbol('text');}catch(e){caught=e instanceof TypeError;}if(!caught||x.text!=='Author effect'||watch.takeRecords().length)throw 'Symbol conversion atomic';for(var value of [null,undefined,0,false]){x.text=value;if(x.text!==String(value)||x.textContent!==String(value))throw 'ordinary DOMString conversion';}"#);}
#[test]
fn option_text_native_and_inert_writer_refusal_is_atomic_and_recovers(){for inert in [false,true]{for property in ["text","textContent"]{for mode in 0..6{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.textContent='One';"}else{"var x=document.getElementById('option');"});run(&mut d,&mut f,&mut p,"var old=x.firstChild,list=x.childNodes,watch=new MutationObserver(function(){});watch.observe(x,{childList:true});");p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);let native=f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.caption.clone(),format!("{:?}",c.select))).collect::<Vec<_>>();let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes());let limit=p.state.retained_limit;let nodes=p.state.node_limit;let extra=p.state.limits.host.extra_nodes;let entry_arenas=p.state.limits.test_entry_arenas;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,4=>p.state.execution_deadline=Some(Instant::now()),_=>if inert{p.state.limits.test_entry_arenas=true;p.state.limits.host.extra_nodes=0;}else{p.state.node_limit=0;}};let source=format!(r"x.{property}=' Replacement\ud800 Z ';");let error=p.runtime.execute(&source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{inert}/{property}/{mode}"));assert!(error.contains("work")||error.contains("allowance")||error.contains("limit")||error.contains("bound"),"{inert}/{property}/{mode}: {error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes()),before);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.caption.clone(),format!("{:?}",c.select))).collect::<Vec<_>>(),native);p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.limits.host.extra_nodes=extra;p.state.limits.test_entry_arenas=entry_arenas;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.firstChild!==old||old.parentNode!==x||old.data!=='One'||list.length!==1||watch.takeRecords().length)throw 'atomic refused replacement';");run(&mut d,&mut f,&mut p,&source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.text!=='Replacement\ud800 Z'||x.textContent!==' Replacement\ud800 Z '||old.parentNode!==null||records.length!==1||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==x.firstChild)throw 'fresh replacement recovery';");
 }}}}
#[test]
fn option_text_reader_limits_refuse_without_mutation_and_recover(){for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{r"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.text=' A\ud800 Z ';"}else{"var x=document.getElementById('option');"});let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("actual option")};let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes());let retained=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_text_get(object).is_err());assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes()),before);p.state.retained_limit=retained;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,if inert{r"if(x.text!=='A\ud800 Z')throw 'inert reader recovery';"}else{"if(x.text!=='One')throw 'native reader recovery';"});}}}
#[test]
fn option_text_native_value_and_display_bounds_apply_to_normalized_fallback_only(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),edge='',over='',space='';for(var n=0;n<4096;n++)edge+='a';over=edge+'b';for(var n=0;n<5000;n++)space+=' ';x.text=edge;");let c=&f.controls[&select];assert_eq!(c.value.chars.len(),4096);assert_eq!(c.caption,"a".repeat(256));let tree=format!("{:?}",d.nodes);let native=format!("{:?}",f.controls[&select].select);p.begin_job();let error=p.runtime.execute("x.text=over;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("4096"),"{error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(format!("{:?}",f.controls[&select].select),native);p.begin_job();run(&mut d,&mut f,&mut p,"x.text=space+'A'+space;if(x.text!=='A'||x.textContent.length!==10001)throw 'normalized fallback admission';");assert_eq!(f.controls[&select].value.text(),"A");run(&mut d,&mut f,&mut p,"x.value='Explicit';x.label='Label';x.text=over;if(x.text!==over||x.textContent!==over||x.value!=='Explicit'||x.label!=='Label')throw 'explicit metadata avoids native fallback truncation';");assert_eq!(f.controls[&select].value.text(),"Explicit");assert_eq!(f.controls[&select].caption,"Label");}
#[test]
fn option_text_native_combined_value_label_editor_payload_refusal_is_atomic(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option');");let payload=f.controls.values().map(|c|{let mut n=c.name.len()+c.value.chars.iter().map(|ch|ch.len_utf8()).sum::<usize>();if let Some(s)=&c.select{for o in &s.options{n+=o.value.len()+o.label.len();}for row in &s.rows{if let forms::SelectRow::Group{label,..}=row{n+=label.len();}}}n}).sum::<usize>();let label=&mut f.controls.get_mut(&select).unwrap().select.as_mut().unwrap().options[1].label;let size=label.len()+128*1024-payload-10;let old=std::mem::replace(label,"z".repeat(size));let tree=format!("{:?}",d.nodes);let native=format!("{:?}",f.controls[&select].select);let editor=f.controls[&select].value.text();let before=(p.state.retained,p.state.dom_commits);p.begin_job();let error=p.runtime.execute("x.text='1234567';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("128 KiB"),"{error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(format!("{:?}",f.controls[&select].select),native);assert_eq!(f.controls[&select].value.text(),editor);assert_eq!((p.state.retained,p.state.dom_commits),before);f.controls.get_mut(&select).unwrap().select.as_mut().unwrap().options[1].label=old;p.begin_job();run(&mut d,&mut f,&mut p,"x.text='Recovered';if(x.text!=='Recovered'||x.value!=='Recovered'||x.label!=='Recovered')throw 'combined payload recovery';");}
#[test]
fn option_text_live_ranges_unselected_fallback_and_text_content_alias_use_real_children(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),select=document.getElementById('select'),r=new Range(),old=x.firstChild;r.selectNodeContents(old);select.selectedIndex=1;x.textContent=' New text ';if(x.text!=='New text'||x.value!=='New text'||x.label!=='New text'||r.startContainer!==x||r.endContainer!==x||r.startOffset!==0||r.endOffset!==0||!r.collapsed||old.parentNode!==null||select.value!=='two')throw 'actual range and alias update';");let c=&f.controls[&select];assert_eq!(c.value.text(),"two");assert_eq!(c.caption,"Second");assert_eq!(c.select.as_ref().unwrap().options[0].label,"New text");}
#[test]
fn option_text_whole_select_character_data_and_resource_descendants_keep_guards(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option');");for source in ["document.getElementById('select').textContent='blocked';","x.firstChild.data='blocked';"]{let tree=format!("{:?}",d.nodes);let native=f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.caption.clone(),format!("{:?}",c.select))).collect::<Vec<_>>();p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.value.text(),c.caption.clone(),format!("{:?}",c.select))).collect::<Vec<_>>(),native);}
 // Adversarial native topology retains a real already admitted INPUT guard.
 let option=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("option")).unwrap();let neighbor=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("neighbor")).unwrap();for node in &mut d.nodes{node.children.retain(|&n|n!=neighbor);}d.nodes[option].children.push(neighbor);p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits);p.begin_job();let error=p.runtime.execute("x.text='blocked';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("controls")||error.contains("structural"),"{error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits),before);
}
